import{_ as a,C as t,o as n,c as o,E as s,a2 as r}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Digital Employee Daily 001 — Position, Ownership, and Authority Before Agent Capability","description":"","frontmatter":{"title":"Digital Employee Daily 001 — Position, Ownership, and Authority Before Agent Capability","date":"2026-08-02","column":"digital-employee","category":"daily","summary":"Workday, ServiceNow, and Microsoft increasingly manage AI workers through persistent ownership, defined roles, scoped authority, and lifecycle controls rather than model capability alone.","cover":"/assets/covers/position-ownership-authority-cover-v2.jpg","sources":["Workday Agent System of Record","ServiceNow Autonomous Workforce","Microsoft Agent 365"],"outline":"deep"},"headers":[],"relativePath":"en/digital-employee/2026-08-02-position-ownership-authority.md","filePath":"en/digital-employee/2026-08-02-position-ownership-authority.md","lastUpdated":1787407830000}'),l={name:"en/digital-employee/2026-08-02-position-ownership-authority.md"};function c(p,e,d,h,g,m){const i=t("ArticleCover");return n(),o("div",null,[s(i,{image:"/assets/covers/position-ownership-authority-cover-v2.jpg",kicker:"Digital Employee · Daily 001",title:"Position, Ownership, and Authority Before Agent Capability",summary:"A Digital Employee begins as an organizational object with a position, accountable owner, and bounded authority; Agent capability is assigned underneath that contract.",version:"DD001",status:"Research Note · 2026-08-02",languageHref:"/zh/digital-employee/2026-08-02-position-ownership-authority",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h1 id="digital-employee-daily-001-—-position-ownership-and-authority-before-agent-capability" tabindex="-1">Digital Employee Daily 001 — Position, Ownership, and Authority Before Agent Capability <a class="header-anchor" href="#digital-employee-daily-001-—-position-ownership-and-authority-before-agent-capability" aria-label="Permalink to &quot;Digital Employee Daily 001 — Position, Ownership, and Authority Before Agent Capability&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>The strongest common signal across current enterprise AI workforce products is not a new reasoning model. It is the move from an unnamed Agent to a managed organizational object.</p><p>Workday emphasizes registration, ownership, role, permissions, lifecycle, cost, and value. ServiceNow packages AI Specialists with defined roles, skill-aligned assignments, authority, workflow policy, and human escalation. Microsoft Agent 365 adds registry, owner assignment, access governance, activation, blocking, and retirement.</p><p>The research judgment is:</p><blockquote><p>A Digital Employee should begin with Position, accountable ownership, and bounded authority. Agent capability is an implementation resource assigned underneath that organizational contract.</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="selected-official-material" tabindex="-1">Selected official material <a class="header-anchor" href="#selected-official-material" aria-label="Permalink to &quot;Selected official material&quot;">​</a></h3><ol><li><strong>Workday Agent System of Record</strong> — selected because it treats agents as members of a blended workforce and defines registration, accountability, visibility, permissions, analytics, and lifecycle management.</li><li><strong>ServiceNow Autonomous Workforce</strong> — selected because it explicitly moves from generic Agents to role-defined AI Specialists that execute jobs with scope, authority, governance, workflow, and escalation.</li><li><strong>Microsoft Agent 365 governance documentation</strong> — selected because it provides concrete administration actions: registry, owner assignment, activation, blocking, policy, access governance, and lifecycle management.</li></ol><p>These are vendor sources. They document product direction and implemented management concepts, but their performance and adoption claims should not be treated as independent evidence without external validation.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-the-managed-object-is-becoming-persistent" tabindex="-1">1. The managed object is becoming persistent <a class="header-anchor" href="#_1-the-managed-object-is-becoming-persistent" aria-label="Permalink to &quot;1. The managed object is becoming persistent&quot;">​</a></h3><p>Workday describes the Agent System of Record as a unified place to register and manage both first-party and third-party agents. Its lifecycle extends from registration and configuration through activation and deactivation. The agent remains visible as an organizational resource even when an individual execution session has ended.</p><p>Microsoft similarly provides an Agent Registry and governance actions for installation, activation, blocking, ownership reassignment, and deletion. This indicates that an enterprise Agent is no longer modeled only as code or a chat session.</p><h3 id="_2-ownership-is-becoming-mandatory" tabindex="-1">2. Ownership is becoming mandatory <a class="header-anchor" href="#_2-ownership-is-becoming-mandatory" aria-label="Permalink to &quot;2. Ownership is becoming mandatory&quot;">​</a></h3><p>Workday asks who owns an agent, what role it has, what it costs, and whether it is delivering value. Microsoft highlights ownerless agents as a governance problem and provides explicit owner-assignment actions. Microsoft Entra extends this further through agent sponsorship and lifecycle workflows.</p><p>Ownership therefore is not merely descriptive metadata. It is the path through which authority, review, incident response, improvement, and retirement become accountable.</p><h3 id="_3-role-and-scope-are-replacing-generic-autonomy" tabindex="-1">3. Role and scope are replacing generic autonomy <a class="header-anchor" href="#_3-role-and-scope-are-replacing-generic-autonomy" aria-label="Permalink to &quot;3. Role and scope are replacing generic autonomy&quot;">​</a></h3><p>ServiceNow&#39;s Autonomous Workforce is organized around AI Specialists such as a Level 1 Service Desk specialist. These specialists have role-specific assignments, skillsets, deliverables, policies, and escalation conditions. The product framing is not “an Agent can do anything”; it is “a governed specialist completes a defined class of organizational work.”</p><p>Workday also describes role-based agent support with responsibilities and permissions tailored to specific roles.</p><h3 id="_4-authority-is-explicitly-bounded" tabindex="-1">4. Authority is explicitly bounded <a class="header-anchor" href="#_4-authority-is-explicitly-bounded" aria-label="Permalink to &quot;4. Authority is explicitly bounded&quot;">​</a></h3><p>ServiceNow links autonomous execution to workflow policy, traceability, and human escalation. Microsoft applies permissions, policies, access packages, blocking, and least-privilege controls. Workday emphasizes precise identity permissioning and whether an agent acts as itself or on behalf of a user.</p><p>The common design direction is clear: useful autonomy is authority inside a boundary, not unrestricted action.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="position-should-be-the-first-organizational-abstraction" tabindex="-1">Position should be the first organizational abstraction <a class="header-anchor" href="#position-should-be-the-first-organizational-abstraction" aria-label="Permalink to &quot;Position should be the first organizational abstraction&quot;">​</a></h3><p>An Agent identifies a technical executor. A Position identifies why the organization permits the executor to exist.</p><p>A Position can define:</p><ul><li>purpose;</li><li>responsibility;</li><li>accepted work classes;</li><li>allowed tools and data;</li><li>decision authority;</li><li>escalation obligations;</li><li>service expectations;</li><li>accountable owner;</li><li>evidence and evaluation requirements.</li></ul><p>This remains stable even when the underlying model, provider, session, or implementation changes.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Organization</span></span>
<span class="line"><span>    ↓ defines</span></span>
<span class="line"><span>Position</span></span>
<span class="line"><span>    ↓ instantiated as</span></span>
<span class="line"><span>Digital Employee</span></span>
<span class="line"><span>    ↓ bound to</span></span>
<span class="line"><span>Agent providers + skills + tools + runtime</span></span></code></pre></div><p>The alternative—starting from an Agent and attaching a prompt—creates a technically capable object without a durable organizational reason, boundary, or owner.</p><h3 id="digital-employee-is-not-equivalent-to-one-agent" tabindex="-1">Digital Employee is not equivalent to one Agent <a class="header-anchor" href="#digital-employee-is-not-equivalent-to-one-agent" aria-label="Permalink to &quot;Digital Employee is not equivalent to one Agent&quot;">​</a></h3><p>The reviewed products often use “agent” as the managed unit, but their governance requirements point toward a broader abstraction. A Digital Employee may use multiple models, temporary sessions, specialist sub-agents, tools, and human approvals while continuing to represent one Position.</p><p>Therefore:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee ≠ model session</span></span>
<span class="line"><span>Digital Employee ≠ prompt</span></span>
<span class="line"><span>Digital Employee ≠ single Agent process</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Digital Employee = persistent organizational work identity</span></span></code></pre></div><h3 id="position-and-ownership-must-be-independently-represented" tabindex="-1">Position and ownership must be independently represented <a class="header-anchor" href="#position-and-ownership-must-be-independently-represented" aria-label="Permalink to &quot;Position and ownership must be independently represented&quot;">​</a></h3><p>The Position defines what work exists. Ownership defines who is accountable for the Digital Employee&#39;s continued operation. Combining them into one field would make reassignment, organizational change, and cross-team governance difficult.</p><p>A minimum registry projection should therefore include both:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">digital_employee</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  position_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  organizational_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  responsibility_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_work_catalog_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  escalation_policy_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lifecycle_status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  runtime_binding_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evaluation_summary_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>This is a research projection, not a frozen implementation schema.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>No direct modification to the TMPA publication set is made by this note. As research input, it strengthens the need for explicit references among organizational role, authority, responsibility, event history, and governance judgment.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>Position, ownership, responsibility, and authority should become first-class architecture objects. The Digital Employee definition should not begin with the selected model or Agent framework.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>The existing PM, DEV, QA, and OPS roles can be treated as early Position definitions. A future Digital Employee Registry should project:</p><ul><li>Position identity;</li><li>human or organizational owner;</li><li>accepted WorkOrder classes;</li><li>allowed tools and providers;</li><li>escalation and completion authority;</li><li>lifecycle and evaluation state.</li></ul><p>The first implementation step should be a read-only projection over current runtime facts, not an immediate rewrite of dispatch behavior.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>Define the minimum Position contract.</li><li>Separate Position, Digital Employee instance, Agent provider, and Session identifiers.</li><li>Define how ownership transfer affects active WorkOrders.</li><li>Compare role-based authority in Workday, ServiceNow, and Microsoft with CodeFlowMu&#39;s current TeamPolicy and FCoP responsibility model.</li><li>Identify evidence required before a Digital Employee can be activated for production work.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Workday, <strong>Agent System of Record</strong>: <a href="https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/artificial-intelligence/agent-system-of-record.html</a></li><li>Workday, <strong>The Workday Agent System of Record Is Now Generally Available</strong>: <a href="https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html" target="_blank" rel="noreferrer">https://blog.workday.com/en-us/managing-ai-powered-future-of-work.html</a></li><li>Workday, <strong>Understanding AI agents</strong>: <a href="https://www.workday.com/en-us/topics/ai/ai-agents.html" target="_blank" rel="noreferrer">https://www.workday.com/en-us/topics/ai/ai-agents.html</a></li><li>ServiceNow, <strong>ServiceNow launches Autonomous Workforce that thinks and acts</strong>: <a href="https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx" target="_blank" rel="noreferrer">https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-launches-Autonomous-Workforce-that-thinks-and-acts-adds-Moveworks-to-the-ServiceNow-AI-Platform/default.aspx</a></li><li>Microsoft Learn, <strong>Microsoft Agent 365 overview</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/overview</a></li><li>Microsoft Learn, <strong>Govern agents using Agent 365</strong>: <a href="https://learn.microsoft.com/en-us/training/modules/agent-365-govern/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/training/modules/agent-365-govern/</a></li><li>Microsoft Learn, <strong>Governance and lifecycle actions for agents</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-365/admin/manage/agent-actions?view=o365-worldwide" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-365/admin/manage/agent-actions?view=o365-worldwide</a></li><li>Microsoft Learn, <strong>Protect agent identities with Microsoft Entra</strong>: <a href="https://learn.microsoft.com/en-us/microsoft-agent-365/admin/capabilities-entra" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/microsoft-agent-365/admin/capabilities-entra</a></li></ol>`,53))])}const f=a(l,[["render",c]]);export{y as __pageData,f as default};
